cat > /tmp/claude-0/s/sweep.py <<'EOF'
import sys, time, json, numpy as np
exec(open('/tmp/claude-0/s/proto.py').read().split('for f in interactive')[0])
Ls = [L for L in labels if L['label'] is not None]; y = np.array([L['label'] for L in Ls])
GRID = dict(min_green_balance=np.arange(.1,.51,.05), min_snr=np.arange(2,5.01,.25), purity=np.arange(.1,.41,.05),
  min_opposite=np.arange(80,141,5), max_off_u=list(np.arange(.5,2.01,.25))+[99], max_axis_dev=list(range(10,46,5))+[180],
  min_aspect=np.arange(2,4.51,.25), min_solid=np.arange(0,.91,.05), nucleus_frac=np.arange(.5,1.01,.1), max_shared=np.arange(.1,.61,.1))
class Ev:
    def __init__(s, f):
        s.s = sess(f); C = s.s.cands
        xy = np.array([(k['cx'], k['cy']) for k in C]).reshape(-1,2)
        s.near = [np.nonzero(np.hypot(*(xy-(L['x'],L['y'])).T) <= nor_lab.radius(L))[0] for L in Ls]
        s.base = {k: v for fl in s.s.filters() for k, v in fl['params'].items()}
    def hits(s, vals):
        fails = s.s.refilter({'values': vals}); ok = np.array([f is None for f in fails])
        return np.array([ok[i].any() if len(i) else False for i in s.near])
def fb(h, yy, beta=1.0):
    tp=(h&(yy==1)).sum(-1); fp=(h&(yy==0)).sum(-1); fn=(~h&(yy==1)).sum(-1); b2=beta*beta
    return (1+b2)*tp/np.maximum(1,(1+b2)*tp+b2*fn+fp)
def pr(h, yy=y):
    tp=(h&(yy==1)).sum(); fp=(h&(yy==0)).sum(); return tp/max(1,tp+fp), tp/max(1,(yy==1).sum()), int(tp), int(fp)
def tune(ev, start, beta=1.0, mask=None, rounds=3):
    m = np.ones(len(y),bool) if mask is None else mask
    cur = dict(start); best = fb(ev.hits(cur)[m], y[m], beta)
    for _ in range(rounds):
        moved=False
        for k, g in GRID.items():
            for v in g:
                v = round(float(v),3); t = dict(cur, **{k: v}); sc = fb(ev.hits(t)[m], y[m], beta)
                if sc > best + 1e-9: best, cur, moved = sc, t, True
        if not moved: break
    return cur, best
if __name__ == '__main__':
    ev = Ev('tl'); t=time.time(); ev.hits(ev.base); print('refilter s', time.time()-t)
EOF
cd /tmp/claude-0/s && python3 sweep.py 2>&1 | grep -v Displ

