cat > /tmp/claude-0/s/presets.py <<'EOF'
import sys; sys.argv=['x']
exec(open('/tmp/claude-0/s/sweep.py').read().split("if __name__")[0])
import interactive
F = list(interactive.FINDERS); E = {f: Ev(f) for f in F}
def tune_shared(start, beta, mask, rounds=2):
    obj=lambda v: np.mean([fb(E[f].hits(dict(E[f].base, **v))[mask], y[mask], beta) for f in F])
    cur=dict(start); best=obj(cur)
    for _ in range(rounds):
        moved=False
        for k,g in GRID.items():
            for v in g:
                t=dict(cur,**{k:round(float(v),3)}); s=obj(t)
                if s>best+1e-9: best,cur,moved=s,t,True
        if not moved: break
    return cur
start=E['tl'].base; allm=np.ones(len(y),bool)
P={}
for nm,beta in (('precise',0.5),('sensitive',2.0)):
    P[nm]=tune_shared(start,beta,allm); print(nm,{k:(start[k],v) for k,v in P[nm].items() if abs(v-start[k])>1e-9})
for f in F:
    print(f, '  own', pr(E[f].hits(E[f].base))[:4], '  tlset', pr(E[f].hits(dict(E[f].base,**start)))[:4],
          '  precise', pr(E[f].hits(dict(E[f].base,**P['precise'])))[:4], '  sensitive', pr(E[f].hits(dict(E[f].base,**P['sensitive'])))[:4])
json.dump(P,open('/tmp/claude-0/s/presets.json','w'))
# held-out: does the direction hold?
rng=np.random.default_rng(2); D={nm:[] for nm in P}
for r in range(3):
    m=np.zeros(len(y),bool)
    for cls in (0,1):
        idx=np.nonzero(y==cls)[0]; rng.shuffle(idx); m[idx[:len(idx)//2]]=True
    for tr in (m,~m):
        te=~tr
        for nm,beta in (('precise',0.5),('sensitive',2.0)):
            v=tune_shared(start,beta,tr,rounds=1)
            for f in F:
                b=pr(E[f].hits(dict(E[f].base,**start))[te],y[te]); a=pr(E[f].hits(dict(E[f].base,**v))[te],y[te])
                D[nm].append((a[0]-b[0],a[1]-b[1]))
for nm in D:
    d=np.array(D[nm]); print(nm,'held-out vs tl set: dP %+.3f dR %+.3f'%tuple(d.mean(0)), 'P up in %.0f%%, R up in %.0f%%'%((d[:,0]>0).mean()*100,(d[:,1]>0).mean()*100))
EOF
cd /tmp/claude-0/s && python3 presets.py 2>&1 | grep -v Displ

