.param .ours { display: none; position: absolute; top: -3px; bottom: -3px; width: 9px; padding: 0; border: 0; background: none; cursor: pointer;
  left: calc(8px + (100% - 16px) * var(--at) - 4.5px); }
.param .ours::after { content: ""; position: absolute; left: 3.5px; top: 0; bottom: 0; width: 2px; border-radius: 1px; background: var(--warn); }
.param.changed .ours { display: block; }
.param.changed .name { color: var(--warn); }
.param input[type=number] { width: 76px; padding: 2px 6px; background: var(--panel); }
.param.bool { grid-template-columns: 1fr auto; }
.param.bool .name { grid-column: 1; }
.param.text input { grid-column: 1 / 3; padding: 2px 6px; background: var(--panel); }
.help { display: inline-flex; align-items: center; justify-content: center; width: 14px; height: 14px; margin-left: 2px; border-radius: 50%;
  border: 1px solid var(--dim); color: var(--dim); font-size: 10px; font-weight: 700; line-height: 1; cursor: help; vertical-align: 1px; }
.help:hover, .help:focus-visible { color: var(--accent); border-color: var(--accent); outline: none; }
#finder-note { margin: 8px 0 0; }

#view { position: relative; display: flex; flex-direction: column; min-width: 0; min-height: 0; margin: var(--pad) 0;
  background: var(--panel); border: 1px solid var(--line); border-radius: var(--r-panel); overflow: hidden; }
.toolbar { display: flex; gap: 10px; align-items: center; height: 52px; padding: 0 var(--pad); border-bottom: 1px solid var(--line); font-size: 13px; }
.toolbar .group { display: flex; gap: 10px; align-items: center; }
.toolbar .grow { flex: 1; }
button.big { padding: 6px 18px; font-size: 14px; font-weight: 600; background: var(--accent); border-color: var(--accent); color: #fff; }
#image-view, #items-view { flex: 1; min-height: 0; display: flex; flex-direction: column; }
#image-view[hidden], #items-view[hidden] { display: none; }
#items-view { overflow-y: auto; padding: var(--pad); }
/* zoom: one rounded segmented control */
.zoom { display: inline-flex; align-items: stretch; border: 1px solid var(--line); border-radius: var(--r-ctl); overflow: hidden; background: var(--panel); }
.zoom button { border: 0; border-radius: 0; background: transparent; width: 32px; font-size: 16px; line-height: 1; padding: 5px 0; }
.zoom button:hover { background: var(--bg); }
#zoom-label { min-width: 44px; text-align: center; align-self: center; font-variant-numeric: tabular-nums; border-left: 1px solid var(--line); border-right: 1px solid var(--line); padding: 5px 0; }
/* the overlay options, folded into one dropdown */
.menu { position: relative; }
.menu summary { list-style: none; cursor: pointer; padding: 5px 12px; border: 1px solid var(--line); border-radius: var(--r-ctl); background: var(--panel); }
.menu summary::-webkit-details-marker { display: none; }
.menu summary::after { content: " ▾"; color: var(--dim); }
.menu .pop { position: absolute; top: calc(100% + 4px); left: 0; z-index: 20; display: flex; flex-direction: column; gap: 8px; min-width: 170px;
  padding: 10px 14px; background: var(--panel); border: 1px solid var(--line); border-radius: var(--r-ctl); box-shadow: 0 6px 18px #0004; }
.menu .pop label { display: flex; align-items: center; gap: 6px; white-space: nowrap; }
.menu .opt { display: flex; align-items: center; gap: 8px; }
.menu .opt label { flex: 1; }
.menu .opt input[type=range] { width: 80px; }
.menu .opt input[type=color] { width: 26px; height: 22px; padding: 0 2px; }
.menu .pop label.num input { width: 58px; padding: 2px 6px; }
/* each view shows only its own tools */
